// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller, uint256 timeOffset) public {
        vm.assume(caller != address(0));
        uint256 warpTime = 1 + (timeOffset % 100000);

        uint256 ticket = 10;
        vm.deal(caller, ticket);

        vm.warp(warpTime);

        vm.prank(caller);
        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, caller))) % 2;

        if (random == 1) {
            assertTrue(c.pot() == ticket);
        } else {
            assertTrue(c.pot() == 0);
        }
    }
}
